function cartScreen(){const cart=getCart();if(!cart.length)return `<section class="page-wrap empty-state"><div class="empty-icon">${icon('bag')}</div><span class="eyebrow">A little room for something lovely</span><h2>Your bag is taking a coffee break.</h2><p>Choose a drink and we’ll make it fresh for you.</p><button class="primary-button" data-action="browse">${icon('coffee')}Explore the menu ${icon('arrow')}</button></section>`;return `<section class="page-wrap"><div class="page-head"><div><span class="eyebrow">${icon('bag')} Almost yours</span><h1 class="page-title">Your coffee bag.</h1><span class="subtle">${cart.reduce((n,x)=>n+x.quantity,0)} freshly made drink${cart.reduce((n,x)=>n+x.quantity,0)===1?'':'s'}</span></div><button class="text-button" data-action="browse">${icon('arrowLeft')} Continue shopping</button></div>${cart.map(x=>`<article class="cart-row"><img src="${h(x.image)}" alt="${h(x.name)}"><div><h3>${icon('coffee')}${h(x.name)}</h3><p>${h(Object.values(x.optionLabels).flat().join(' · '))}</p><div class="quantity-control" style="margin-top:12px;width:max-content"><button aria-label="Decrease quantity" data-action="cart-minus" data-id="${h(x.lineId)}">${icon('minus')}</button><span>${x.quantity}</span><button aria-label="Increase quantity" data-action="cart-plus" data-id="${h(x.lineId)}">${icon('plus')}</button></div></div><strong class="row-price">${money(x.unitPrice*x.quantity)}</strong><button class="remove" aria-label="Remove ${h(x.name)}" data-action="remove" data-id="${h(x.lineId)}">${icon('trash')}</button><button class="text-button" data-action="edit" data-id="${h(x.lineId)}">${icon('sparkle')} Edit</button></article>`).join('')}<div class="summary"><div class="summary-line"><span>${icon('receipt')} Subtotal</span><span>${money(subtotal(cart))}</span></div>${menu.fees?.service?`<div class="summary-line"><span>${icon('sparkle')} Service fee</span><span>${money(menu.fees.service)}</span></div>`:''}<div class="summary-line total"><span>Total</span><span>${money(subtotal(cart)+(menu.fees?.service||0))}</span></div><button class="primary-button" data-action="checkout">${icon('bag')} Review your order ${icon('arrow')}</button></div></section>`}
function checkoutScreen(){const cart=getCart();if(!cart.length){route='cart';return cartScreen()}return `<section class="page-wrap"><div class="page-head"><div><span class="eyebrow">${icon('receipt')} One last look</span><h1 class="page-title">Your order, just right.</h1><span class="subtle">No payment is taken for this demonstration.</span></div></div><div class="checkout-layout"><div class="review-card"><span class="eyebrow">${icon('bag')} Order summary</span>${cart.map(x=>`<div class="review-item"><img class="review-product-image" src="${h(x.image)}" alt="${h(x.name)}"><span><b>${x.quantity} × ${h(x.name)}</b><br><small class="subtle">${h(Object.values(x.optionLabels).flat().join(' · '))}</small></span><strong>${money(x.unitPrice*x.quantity)}</strong></div>`).join('')}<div class="summary-line total"><span>Total</span><span>${money(subtotal(cart)+(menu.fees?.service||0))}</span></div></div><aside class="confirm-card"><span class="eyebrow">${icon('sparkle')} Ready when you are</span><h3>Made fresh, just for you.</h3><p>Confirming sends your order to the café queue. You can review the drinks and customizations above.</p><button class="primary-button" data-action="confirm">${icon('check')} Confirm order · ${money(subtotal(cart)+(menu.fees?.service||0))}</button><button class="cancel-link" data-action="cancel">${icon('arrowLeft')} Cancel and return to bag</button></aside></div></section>`}
function receiptScreen(){const o=lastOrder;if(!o)return homeScreen();return `<section class="receipt fade-in"><div class="success-mark">${icon('check')}</div><span class="eyebrow">${icon('sparkle')} We've got it from here</span><h1>Your order has been received!</h1><p class="receipt-number">${h(o.id)}</p><p class="subtle">${new Date(o.createdAt).toLocaleString()} · PENDING</p><div class="summary">${o.items.map(x=>`<div class="review-item"><img class="review-product-image" src="${h(x.image)}" alt="${h(x.name)}"><span>${x.quantity} × ${h(x.name)}<br><small class="subtle">${h(Object.values(x.optionLabels||{}).flat().join(' · '))}</small></span><b>${money(x.quantity*x.unitPrice)}</b></div>`).join('')}<div class="summary-line total"><span>Total</span><span>${money(o.total)}</span></div></div><div class="receipt-actions"><button class="secondary-button" data-action="print">${icon('receipt')} Print receipt</button><button class="primary-button" data-action="new-order">${icon('coffee')} Start a new order</button></div><p class="subtle receipt-note">Keep your order number handy at pickup.</p></section>`}
function gestureIcon(name){if(name==='fist')return '<span class="gesture-emoji" aria-hidden="true">✊</span>';const hand='M8 12V5a1.5 1.5 0 0 1 3 0v6-8a1.5 1.5 0 0 1 3 0v8-6a1.5 1.5 0 0 1 3 0v7-4a1.5 1.5 0 0 1 3 0v6c0 5-3 8-7 8h-1c-2 0-3.5-1-4.5-2.5L4 14a1.7 1.7 0 0 1 2.5-2.2L8 13';const smallHand=`<g transform="translate(2 2) scale(.72)"><path d="${hand}"/></g>`;const paths={one:'<path d="M7 13V8a1.5 1.5 0 0 1 3 0v4-8a1.5 1.5 0 0 1 3 0v8-5a1.5 1.5 0 0 1 3 0v5-3a1.5 1.5 0 0 1 3 0v5c0 5-3 8-7 8h-1c-2 0-3.5-1-4.5-2.5L3 16a1.7 1.7 0 0 1 2.5-2.2L7 15"/>',two:'<path d="M6 13V8a1.5 1.5 0 0 1 3 0v4-7a1.5 1.5 0 0 1 3 0v7-8a1.5 1.5 0 0 1 3 0v8-5a1.5 1.5 0 0 1 3 0v5-3a1.5 1.5 0 0 1 3 0v5c0 5-3 8-7 8h-1c-2 0-3.5-1-4.5-2.5L3 16a1.7 1.7 0 0 1 2.5-2.2L6 15"/>',palm:`<path d="${hand}"/>`,left:`${smallHand}<path d="M23 8H14m0 0 3-3m-3 3 3 3"/>`,right:`${smallHand}<path d="M1 8h9m0 0L7 5m3 3-3 3"/>`,pinch:'<path d="M8 12V6a1.5 1.5 0 0 1 3 0v5-7a1.5 1.5 0 0 1 3 0v7-5a1.5 1.5 0 0 1 3 0v6l1-2a1.7 1.7 0 0 1 3 1l-2 6c-.6 2-2.2 3-4.5 3h-2c-2 0-3.5-1-4.5-2.5L4 14a1.7 1.7 0 0 1 2.5-2.2L8 13"/><path d="M3 4l2 2m-2 0 2-2"/>',up:`${smallHand}<path d="M19 9V1m0 0-3 3m3-3 3 3"/>`,down:`${smallHand}<path d="M19 2v8m0 0-3-3m3 3 3-3"/>`,thumbs_up:'<path d="M7 10v11H4V10h3m3 11h6.5a2 2 0 0 0 1.9-1.4l2-6A2 2 0 0 0 18.5 11H14l.7-4.1A2 2 0 0 0 12.8 4L10 10v11z"/>',thumbs_down:'<path d="M7 14V3H4v11h3m3-11h6.5a2 2 0 0 1 1.9 1.4l2 6A2 2 0 0 1 18.5 13H14l.7 4.1a2 2 0 0 1-1.9 2.9L10 14V3z"/>',fist:'<path d="M6 12V7.5A1.5 1.5 0 0 1 9 7v4-5a1.5 1.5 0 0 1 3 0v5-4a1.5 1.5 0 0 1 3 0v4-3a1.5 1.5 0 0 1 3 0v5c0 5-3 8-7 8h-1c-2 0-3.5-1-4.5-2.5L3 15a1.7 1.7 0 0 1 2.5-2.2L6 13"/>',keyboard:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="M6 9h.01M10 9h.01M14 9h.01M18 9h.01M6 12h.01M10 12h.01M14 12h.01M18 12h.01M8 15h8"/>'};return `<svg class="gesture-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]}</svg>`}
function helpScreen(){
  const gestures=[['one','Point','Move the hand cursor over a control'],['pinch','Pinch and release','Select the highlighted control'],['fist','Closed fist','Hold briefly to cancel and go back one step'],['left','Move left','Focus the previous choice'],['right','Move right','Focus the next choice'],['up','Move up','Scroll up'],['down','Move down','Scroll down']];
  return `<section class="page-wrap help-page"><div class="help-heading"><span class="eyebrow">${icon('hand')} TOUCHLESS ORDERING</span><h1 class="page-title">Your hand is the pointer.</h1><p class="subtle">Keep one hand in the camera view. Move your index finger to point. Wait for the control highlight, then pinch and release on that same control to select it. For checkout, review the order and hold a pinch on Confirm until it submits.</p></div><div class="gesture-howto"><b>${icon('sparkle')} Order in five steps</b><span>1. Point at a drink</span><span>2. Pinch to customize</span><span>3. Choose options and add</span><span>4. Review your bag</span><span>5. Hold pinch to confirm</span></div><div class="gesture-grid">${gestures.map(([key,title,description])=>`<div class="gesture-tile"><b>${gestureIcon(key)}</b><strong>${title}</strong><small>${description}</small></div>`).join('')}</div><div class="camera-preview"><div class="camera-preview-heading"><div><span class="eyebrow">${icon('camera')} LIVE CAMERA</span><b>Hand control</b><p>Allow camera access. Video stays on this device.</p></div><button id="cameraToggle" class="camera-toggle" type="button" aria-pressed="${!!browserCameraStream}" data-action="toggle-camera">${icon(browserCameraStream?'close':'camera')} ${browserCameraStream?'Close camera':'Open camera'}</button></div><span id="helpCameraStatus" class="camera-status">${browserCameraStream?'Camera on · move your hand to see the pointer':cameraDisabled?'Camera off':document.querySelector('#cameraLabel').textContent}</span></div></section>`;
}async function enableBrowserCamera(){const video=document.querySelector('#cameraSource');const status=document.querySelector('#helpCameraStatus');const button=document.querySelector('#cameraToggle');try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Camera access requires localhost or a secure browser page.');cameraDisabled=false;preferBrowserCamera=true;browserCameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480},frameRate:{ideal:24,max:30}},audio:false});if(!video)throw new Error('Camera video element is unavailable.');video.srcObject=browserCameraStream;await video.play();document.querySelector('#handCameraWidget')?.classList.remove('is-minimized');syncCameraUI();document.querySelector('#cameraDot').style.background='var(--green)';document.querySelector('.camera-pill').classList.remove('offline');try{await loadHandTracker();document.querySelector('#cameraLabel').textContent='Camera on - gestures ready';connectGestures()}catch(trackerError){document.querySelector('#cameraLabel').textContent='Camera preview only';if(status)status.textContent=trackerError.message;showToast(trackerError.message)}}catch(error){if(browserCameraStream)browserCameraStream.getTracks().forEach(track=>track.stop());browserCameraStream=null;preferBrowserCamera=false;cameraDisabled=true;if(video)video.srcObject=null;if(status)status.textContent=error.name==='NotAllowedError'?'Camera permission was blocked':error.name==='NotFoundError'?'No camera was found':error.name==='NotReadableError'?'Camera is busy in another app':'Camera could not be opened';if(button){button.innerHTML=icon('camera')+' Open camera';button.setAttribute('aria-pressed','false')}showToast(status?.textContent||error.message)}}
function stopBrowserCamera(){preferBrowserCamera=false;if(cameraFrameTimer){clearInterval(cameraFrameTimer);cameraFrameTimer=null}cameraFramePending=false;if(gestureSocket){const ws=gestureSocket;gestureSocket=null;if(ws.readyState<2)ws.close()}if(browserCameraStream){browserCameraStream.getTracks().forEach(track=>track.stop());browserCameraStream=null}const source=document.querySelector('#cameraSource');if(source)source.srcObject=null;const preview=document.querySelector('#browserCameraPreview');if(preview){preview.pause();preview.srcObject=null;preview.hidden=true}const canvas=document.querySelector('#handLandmarkCanvas');canvas?.getContext('2d')?.clearRect(0,0,canvas.width,canvas.height);if(handTracker){handTracker.close();handTracker=null}handPinching=false;handPinchOrigin=null;handPinchTarget=null;pinchCandidateSince=null;pinchReleaseSince=null;handDragged=false;handCursorX=null;handCursorY=null;lastHandPoints=null;lastHandSeenAt=0;clearHandTarget();const pointer=document.querySelector('#handPointer');if(pointer){pointer.hidden=true;pointer.classList.remove('is-grabbing');pointer.removeAttribute('data-carry')}syncCameraUI()}
function toggleCamera(){if(!browserCameraStream){enableBrowserCamera();return}cameraDisabled=true;stopBrowserCamera();const status=document.querySelector('#helpCameraStatus');const button=document.querySelector('#cameraToggle');if(status)status.textContent='Camera off';if(button){button.innerHTML=icon('camera')+' Open camera';button.setAttribute('aria-pressed','false')}const label=document.querySelector('#cameraLabel');if(label)label.textContent='Camera off';document.querySelector('.camera-pill')?.classList.add('offline')}
function kitchenScreen(){return `<section class="page-wrap"><div class="page-head"><div><span class="eyebrow">For the people behind the counter</span><h1 class="page-title">Kitchen orders.</h1><span class="subtle">Updates refresh automatically.</span></div><button class="secondary-button" data-action="refresh-orders">Refresh</button></div><div class="admin-tabs"><button class="filter-chip selected">All orders</button><span class="subtle">Live queue</span></div><div class="admin-grid" id="orderGrid"><p class="subtle">Loading ordersâ€¦</p></div></section>`}
function renderOrders(orders){const el=document.querySelector('#orderGrid');if(!el)return;el.innerHTML=orders.length?orders.map(o=>`<article class="order-card"><header><h3>${h(o.id)}</h3><span class="status-badge">${h(o.status)}</span></header><p>${new Date(o.createdAt).toLocaleString()}<br>${o.items.map(x=>`${x.quantity} Ã— ${h(x.name)} â€” ${h(Object.values(x.optionLabels||{}).flat().join(', '))}`).join('<br>')}<br><b>${money(o.total)}</b></p><select data-status-id="${h(o.id)}">${['PENDING','PREPARING','READY','COMPLETED'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></article>`).join(''):'<p class="subtle">No orders yet. Confirmed customer orders will appear here.</p>'}
function bind(){document.querySelector('#search')?.addEventListener('input',e=>{query=e.target.value;const pos=e.target.selectionStart;render();const el=document.querySelector('#search');el?.focus();el?.setSelectionRange(pos,pos)});document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;render()});document.querySelectorAll('[data-open-product]').forEach(el=>el.onclick=e=>{if(e.target.closest('button'))return;openProduct(el.dataset.openProduct)});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.id));document.querySelectorAll('[data-set-option]').forEach(b=>b.onclick=()=>{opts[b.dataset.setOption]=b.dataset.value;render()});document.querySelectorAll('[data-addon]').forEach(c=>c.onchange=()=>{const id=c.dataset.addon;opts.addons=c.checked?[...opts.addons,id]:opts.addons.filter(x=>x!==id);render()});document.querySelectorAll('[data-status-id]').forEach(s=>s.onchange=async()=>{try{await changeStatus(s.dataset.statusId,s.value);renderKitchen()}catch(e){showToast(e.message)}})}
function openProduct(id){const p=product(id);if(!p)return;chosen=id;editing=null;opts=defaults();qty=1;route='detail';render()}
function action(name,id){switch(name){case'enable-camera':case'toggle-camera':toggleCamera();break;case'browse':if(route!=='home'){go('home');requestAnimationFrame(()=>document.querySelector('#menu')?.scrollIntoView({behavior:'smooth'}))}else document.querySelector('#menu')?.scrollIntoView({behavior:'smooth'});break;case'help':go('help');break;case'customer-login':customerAuthMode='login';customerAuthError='';go('customer-login');break;case'customer-register':customerAuthMode='register';customerAuthError='';go('customer-register');break;case'customer-logout':logoutCustomer().catch(()=>{}).finally(()=>{customerIdentity=null;go('home');showToast('You are signed out')});break;case'admin-login':openAdmin();break;case'detail':openProduct(id);break;case'quick-add':{const p=product(id);addItem(lineItem(p));showToast(`${p.name} added to your bag`);break}case'back':go('home');break;case'qty-minus':qty=Math.max(1,qty-1);render();break;case'qty-plus':qty=Math.min(20,qty+1);render();break;case'add-detail':{const item=lineItem(product(chosen),opts,qty);if(editing)replaceItem(editing,item);else addItem(item);showToast(editing?'Your drink was updated':'Added to your bag');editing=null;go('home');break}case'cart':go('cart');break;case'remove':removeItem(id);render();break;case'cart-minus':{const x=getCart().find(i=>i.lineId===id);setQuantity(id,x.quantity-1);render();break}case'cart-plus':{const x=getCart().find(i=>i.lineId===id);setQuantity(id,x.quantity+1);render();break}case'edit':{const x=getCart().find(i=>i.lineId===id);chosen=x.productId;editing=id;opts=x.options;qty=x.quantity;route='detail';render();break}case'checkout':go('checkout');break;case'cancel':go('cart');break;case'confirm':confirmOrder();break;case'print':window.print();break;case'new-order':clearCart();lastOrder=null;category='All Coffee';query='';go('home');break;case'refresh-orders':renderKitchen();break}}
async function confirmOrder(){const button=document.querySelector('[data-action="confirm"]');if(!button)return;button.disabled=true;button.textContent='Sending to the cafÃ©â€¦';try{lastOrder=await submitOrder(getCart());clearCart();go('receipt')}catch(e){showToast(e.message);button.disabled=false;button.textContent='Please try again'}}
async function renderKitchenLegacy(){const orders=await getOrders();renderOrders(orders)}
document.querySelector('#cartButton').onclick=()=>go('cart');document.querySelector('#cameraHeaderToggle')?.addEventListener('click',toggleCamera);document.querySelector('#accountButton')?.addEventListener('click',()=>go(customerIdentity?'customer-account':'customer-login'));document.querySelector('#helpButton').onclick=()=>go('help');document.querySelector('#handWidgetClose').onclick=toggleCamera;document.querySelector('#handWidgetMinimize').onclick=event=>{const widget=document.querySelector('#handCameraWidget');widget.classList.toggle('is-minimized');event.currentTarget.textContent=widget.classList.contains('is-minimized')?'+':'-' };document.querySelector('#languageSelect')?.addEventListener('change',e=>{language=e.target.value;showToast('Language setting updated')});document.querySelector('#modal').onclick=e=>{if(e.target.id==='modal')e.target.hidden=true};window.addEventListener('cartchange',()=>{document.querySelector('#cartCount').textContent=getCart().reduce((n,x)=>n+x.quantity,0)});window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(route==='detail')go('home');else if(route==='checkout')go('cart')}if(route==='home'&&e.key==='Enter'&&document.activeElement===document.body)document.querySelector('[data-action="browse"]')?.click()});
document.addEventListener('submit',async event=>{
  const form=event.target;
  if(form.id==='customerAuthForm'){
    event.preventDefault();
    const submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;
    const payload=Object.fromEntries(new FormData(form));
    try{
      customerIdentity=customerAuthMode==='register'?await registerCustomer(payload):await loginCustomer(payload);
      customerAuthError='';go('customer-account');showToast(customerAuthMode==='register'?'Your account is ready':'Welcome back');
    }catch(error){customerAuthError=error.message;render()}
    finally{const next=document.querySelector('#customerAuthForm [type="submit"]');if(next)next.disabled=false}
  }
  if(form.id==='contactMessageForm'){
    event.preventDefault();const submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;
    try{await sendContactMessage(Object.fromEntries(new FormData(form)));form.reset();showToast('Thanks — your message has been sent to the café team')}catch(error){showToast(error.message)}
    finally{const next=document.querySelector('#contactMessageForm [type="submit"]');if(next)next.disabled=false}
  }
});startSession(()=>{const m=document.querySelector('#modal');m.innerHTML='<div class="modal"><button class="modal-close" aria-label="Close">Ã—</button><span class="eyebrow">Still there?</span><h2>Your session is about to reset.</h2><p>For the next customerâ€™s privacy, this kiosk clears an idle order shortly.</p><button class="primary-button" id="stayButton">Keep ordering</button></div>';m.hidden=false;m.querySelector('.modal-close').onclick=()=>m.hidden=true;m.querySelector('#stayButton').onclick=()=>m.hidden=true},()=>{clearCart();lastOrder=null;editing=null;chosen=null;document.querySelector('#modal').hidden=true;showToast('Your session has been cleared');go('home')});
window.addEventListener('menuupdate',event=>{menu=event.detail;render()});
async function init(){view.innerHTML='<section class="menu-loading"><span class="loading-cup">â˜•</span><p>Preparing your coffee menuâ€¦</p><span class="loading-bar"></span></section>';try{menu=await loadMenu();if(location.hash==="#contact"){route="contact";activeSection="contact"}try{customerIdentity=await getCustomerSession()}catch{}render();try{const permission=await navigator.permissions?.query({name:"camera"});if(permission?.state==="granted")enableBrowserCamera()}catch{}}catch(e){view.innerHTML=`<section class="empty-state menu-error"><div class="cup">â˜•</div><span class="eyebrow">WE COULDNâ€™T LOAD THE MENU</span><h2>The cafÃ© is still here.</h2><p>${h(e.message)}. Check that the server is running, then try again.</p><button class="primary-button" id="retryMenu">Try again</button></section>`;document.querySelector('#retryMenu')?.addEventListener('click',init)}}
// Gesture socket connects only when the backend's camera dependencies and a camera are available.
function connectGesturesLegacy(){const proto=location.protocol==='https:'?'wss':'ws';const ws=new WebSocket(`${proto}://${location.host}/ws/gestures`);ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.type==='error'){if(!browserCameraStream){document.querySelector('#cameraLabel').textContent='Gesture tracking unavailable';document.querySelector('.camera-pill').classList.add('offline')}const help=document.querySelector('#helpCameraStatus');if(help)help.textContent=browserCameraStream?'Camera preview on':'Gesture tracking unavailable';return}if(m.type==='status'||m.type==='gesture'){const active=m.camera==='connected'||!!browserCameraStream;document.querySelector('#cameraDot').style.background=active?'var(--green)':'#bd6049';document.querySelector('#cameraLabel').textContent=browserCameraStream?'Camera preview on':m.camera==='connected'?(m.trackingAvailable===false?'Camera preview only':m.tracking?'Hand detected':'Camera connected'):'Camera unavailable';const help=document.querySelector('#helpCameraStatus');if(help)help.textContent=document.querySelector('#cameraLabel').textContent;if(m.preview){const preview=document.querySelector('#serverCameraPreview');if(preview&&!browserCameraStream){preview.src=`data:image/jpeg;base64,${m.preview}`;preview.hidden=false}}}if(m.type==='gesture')handleGesture(m.gesture)};ws.onerror=()=>{document.querySelector('#cameraLabel').textContent='Gesture controls offline';document.querySelector('.camera-pill').classList.add('offline')};ws.onclose=()=>{document.querySelector('#cameraLabel').textContent='Camera unavailable';document.querySelector('.camera-pill').classList.add('offline');setTimeout(connectGestures,5000)}}
let gestureFocus=0;
function gestureTargets(){const selectors={home:'[data-category],.story-product-photo,.story-order-button,.story-quick-add,[data-action="detail"],[data-action="quick-add"],[data-action="browse"]',detail:'[data-set-option],[data-addon],[data-action="qty-minus"],[data-action="qty-plus"],[data-action="add-detail"]',cart:'[data-action="edit"],[data-action="remove"],[data-action="cart-minus"],[data-action="cart-plus"],[data-action="checkout"]',checkout:'[data-action="confirm"],[data-action="cancel"]',receipt:'[data-action="print"],[data-action="new-order"]',help:'#cameraToggle',kitchen:'[data-status-id],#refreshOrders,#adminLogout','admin-login':'#adminEmail,#adminPassword,.show-password,.login-submit'};const common=[...document.querySelectorAll('[data-section],#cartButton,#helpButton,#accountButton,#cameraHeaderToggle,#view button,#view label,[data-hand-target]')];return [...new Set([...common,...document.querySelectorAll(selectors[route]||'')])].filter(el=>!el.disabled&&!el.hidden)}
function productTargetId(element){return element?.closest('[data-id]')?.dataset.id||element?.dataset.id||null}
let gestureScrollFrame=0;
function scrollByGesture(distance){
  if(gestureScrollFrame)cancelAnimationFrame(gestureScrollFrame);
  const panel=route==='detail'?document.querySelector('.customization-panel'):null;
  const scroller=panel&&panel.scrollHeight>panel.clientHeight?panel:(document.scrollingElement||document.documentElement);
  const start=scroller.scrollTop,started=performance.now(),duration=220;
  const step=now=>{const progress=Math.min(1,(now-started)/duration);const eased=1-Math.pow(1-progress,3);scroller.scrollTop=start+distance*eased;if(progress<1)gestureScrollFrame=requestAnimationFrame(step);else gestureScrollFrame=0};
  gestureScrollFrame=requestAnimationFrame(step);
}
function handleGesture(gesture){
  registerActivity();
  if(gesture==='cancel'){
    if(route==='detail'){
      const returnToBag=!!editing;editing=null;chosen=null;go(returnToBag?'cart':'home');showToast('Customization cancelled');
    }else if(route==='checkout'){
      go('cart');showToast('Checkout cancelled. Your bag is unchanged.');
    }else if(route==='cart'||route==='help'){
      go('home');
    }
    return;
  }
  if(gesture==='confirm'){
    const target=currentHandTarget;
    const targetReady=!!target&&Date.now()-handTargetSince>=350;
    if(route==='checkout'&&handPinching&&handPinchTarget===target&&targetReady&&target?.matches('[data-action="confirm"]'))confirmOrder();
    return;
  }
  if(gesture==='next'||gesture==='previous'){
    const targets=gestureTargets();if(!targets.length)return;
    gestureFocus=(gestureFocus+(gesture==='next'?1:-1)+targets.length)%targets.length;
    const next=targets[gestureFocus];next.focus({preventScroll:true});next.scrollIntoView({behavior:'smooth',block:'nearest'});return;
  }
  if(gesture==='scroll_up'||gesture==='scroll_down'){
    const distance=Math.round(innerHeight*.68)*(gesture==='scroll_up'?-1:1);
    scrollByGesture(distance);
  }
}// Replace the original editorial landing panel with the reference-inspired kiosk menu.
homeScreen=()=>renderCustomerHome(menu,category,query);
const renderProductDetail=detailScreen;
detailScreen=()=>`<div class="catalog-underlay" aria-hidden="true">${renderCustomerHome(menu,category,query)}</div><div class="customize-backdrop"><div class="customization-panel"><button class="customize-close" data-action="back" aria-label="Close customization">Ã—</button>${renderProductDetail()}</div></div>`;
let adminIdentity='',adminOrders=[],loginError='',adminTab='orders',adminMenuData=null,adminContactData=null,adminUsers=null,adminMessages=[];
const renderCustomerApp=render;
render=function(){
  if(route==='admin-login'){
    document.body.classList.add('admin-mode','admin-login-mode');
    view.innerHTML=renderAdminLogin(loginError);
    const form=document.querySelector('#adminLoginForm');
    form?.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('.login-submit');button.disabled=true;button.querySelector('span').textContent='Signing inâ€¦';try{const result=await loginAdmin(form.email.value,form.password.value);adminIdentity=result.email;loginError='';go('kitchen')}catch(error){loginError=error.message;render()}finally{const next=document.querySelector('.login-submit');if(next){next.disabled=false;next.querySelector('span').textContent='Sign in to dashboard'}}});
    document.querySelector('.show-password')?.addEventListener('click',event=>{const input=document.querySelector('#adminPassword');const show=input.type==='password';input.type=show?'text':'password';event.currentTarget.textContent=show?'Hide':'Show'});
    return;
  }
  if(route==='kitchen'){
    document.body.classList.add('admin-mode');document.body.classList.remove('admin-login-mode');
    renderAdminView();renderKitchen();return;
  }
  document.body.classList.remove('admin-mode','admin-login-mode');renderCustomerApp();
};
async function openAdmin(){try{const session=await getAdminSession();adminIdentity=session.email;loginError='';go('kitchen')}catch{loginError='';go('admin-login')}}
function renderAdminView(){view.innerHTML=renderAdminDashboard(adminIdentity,adminOrders,adminTab,adminMenuData,adminContactData,adminUsers,adminMessages);attachAdminDashboard()}
async function renderKitchen(){if(route!=='kitchen')return;try{adminOrders=await getOrders();if(route!=='kitchen')return;if(adminTab==='orders')renderAdminView();else refreshAdminOrderCountsUI()}catch(error){if(error.message==='Admin login required'){adminIdentity='';clearInterval(kitchenRefresh);route='admin-login';render()}else showToast(error.message)}}
function refreshAdminOrderCountsUI(){for(const status of ['PENDING','PREPARING','READY','COMPLETED']){const node=document.querySelector(`[data-status-count="${status}"]`);if(node)node.textContent=adminOrders.filter(order=>order.status===status).length}const orderCount=document.querySelector('[data-admin-tab="orders"] i');if(orderCount)orderCount.textContent=adminOrders.length}
async function refreshAdminOrderCounts(){if(route!=='kitchen')return;try{adminOrders=await getOrders();if(adminTab==='orders')renderAdminView();else refreshAdminOrderCountsUI()}catch(error){if(error.message==='Admin login required')openAdmin()}}
async function openAdminTab(tab){adminTab=tab;renderAdminView();try{if(tab==='products'||tab==='categories'||tab==='settings')adminMenuData=await getAdminMenu();if(tab==='contact')adminContactData=await getAdminContact();if(tab==='users')adminUsers=await getAdminUsers();if(tab==='messages')adminMessages=await getAdminMessages();renderAdminView()}catch(error){showToast(error.message)}}
async function persistAdminMenu(){try{adminMenuData=await saveAdminMenu(adminMenuData);window.dispatchEvent(new CustomEvent('menuupdate',{detail:adminMenuData}));renderAdminView();showToast('Menu saved')}catch(error){try{adminMenuData=await getAdminMenu()}catch{}renderAdminView();throw error}}
function attachAdminDashboard(){
  document.querySelector('#adminLogout')?.addEventListener('click',async()=>{await logoutAdmin();adminIdentity='';adminOrders=[];clearInterval(kitchenRefresh);go('home')});
  document.querySelector('#adminCameraToggle')?.addEventListener('click',toggleCamera);document.querySelector('#refreshOrders')?.addEventListener('click',()=>adminTab==='orders'?renderKitchen():refreshAdminOrderCounts());
  document.querySelectorAll('[data-admin-tab]').forEach(button=>button.addEventListener('click',()=>openAdminTab(button.dataset.adminTab)));
  document.querySelector('#orderSearch')?.addEventListener('input',event=>{const q=event.target.value.trim().toLowerCase();document.querySelectorAll('.admin-order-card').forEach(card=>card.hidden=!card.dataset.searchText.includes(q))});
  document.querySelectorAll('[data-status-id]').forEach(select=>select.addEventListener('change',async()=>{try{await changeStatus(select.dataset.statusId,select.value);await renderKitchen()}catch(error){showToast(error.message);if(error.message==='Admin login required')openAdmin()}}));
  document.querySelectorAll('[data-toggle-product]').forEach(button=>button.addEventListener('click',async()=>{try{const item=adminMenuData.products.find(product=>product.id===button.dataset.toggleProduct);item.available=!item.available;await persistAdminMenu()}catch(error){showToast(error.message)}}));
  document.querySelectorAll('[data-delete-product]').forEach(button=>button.addEventListener('click',async()=>{if(!confirm('Remove this product from the menu?'))return;try{adminMenuData.products=adminMenuData.products.filter(product=>product.id!==button.dataset.deleteProduct);await persistAdminMenu()}catch(error){showToast(error.message)}}));
  document.querySelectorAll('[data-edit-product]').forEach(button=>button.addEventListener('click',()=>{const item=adminMenuData.products.find(product=>product.id===button.dataset.editProduct);const form=document.querySelector('#productForm');if(!item||!form)return;form.elements.originalId.value=item.id;form.elements.name.value=item.name;form.elements.category.value=item.category;form.elements.price.value=item.price;form.elements.image.value=item.image;form.elements.description.value=item.description;form.elements.available.checked=item.available;form.querySelectorAll('[name="customizations"]').forEach(input=>input.checked=item.customizations.includes(input.value));document.querySelector('#productFormHeading').textContent=`Edit ${item.name}`;form.querySelector('[type="submit"]').textContent='Save changes';form.scrollIntoView({behavior:'smooth',block:'center'})}));
  document.querySelector('#productForm')?.addEventListener('reset',()=>setTimeout(()=>{const form=document.querySelector('#productForm');if(form){form.elements.originalId.value='';document.querySelector('#productFormHeading').textContent='Add a drink';form.querySelector('[type="submit"]').textContent='Save product'}},0));
  document.querySelector('#productForm')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),originalId=data.get('originalId'),name=String(data.get('name')).trim(),customizations=data.getAll('customizations');const product={id:originalId||name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),name,category:data.get('category'),description:String(data.get('description')||'').trim(),price:Number(data.get('price')),image:String(data.get('image')).trim(),available:data.has('available'),customizations};try{if(originalId){const index=adminMenuData.products.findIndex(item=>item.id===originalId);adminMenuData.products[index]=product}else adminMenuData.products.push(product);await persistAdminMenu()}catch(error){showToast(error.message)}});
  document.querySelector('#categoryForm')?.addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.currentTarget),name=String(data.get('category')).trim();try{if(adminMenuData.categories.some(category=>category.toLowerCase()===name.toLowerCase()))throw new Error('That category already exists');adminMenuData.categories.push(name);await persistAdminMenu()}catch(error){showToast(error.message)}});
  document.querySelectorAll('[data-rename-category]').forEach(button=>button.addEventListener('click',async()=>{const oldName=button.dataset.renameCategory,newName=prompt('Rename category',oldName)?.trim();if(!newName||newName===oldName)return;try{if(adminMenuData.categories.some(category=>category.toLowerCase()===newName.toLowerCase()))throw new Error('That category already exists');adminMenuData.categories=adminMenuData.categories.map(category=>category===oldName?newName:category);adminMenuData.products.forEach(product=>{if(product.category===oldName)product.category=newName});await persistAdminMenu()}catch(error){showToast(error.message)}}));document.querySelectorAll('[data-delete-category]').forEach(button=>button.addEventListener('click',async()=>{adminMenuData.categories=adminMenuData.categories.filter(category=>category!==button.dataset.deleteCategory);try{await persistAdminMenu()}catch(error){showToast(error.message)}}));
  document.querySelector('#contactForm')?.addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.currentTarget);const contact=Object.fromEntries(['name','email','phone','address','hours','website'].map(key=>[key,String(data.get(key)||'').trim()]));try{adminContactData=await saveAdminContact(contact);window.dispatchEvent(new CustomEvent('menuupdate',{detail:{...menu,contact:adminContactData}}));renderAdminView();showToast('Café contact details saved')}catch(error){showToast(error.message)}});
  document.querySelector('#userForm')?.addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.currentTarget),id=String(data.get('id')||''),user={name:String(data.get('name')).trim(),email:String(data.get('email')).trim(),phone:String(data.get('phone')||'').trim()};try{await saveAdminUser(user,id);adminUsers=await getAdminUsers();renderAdminView();showToast(id?'Customer updated':'Customer added')}catch(error){showToast(error.message)}});
  document.querySelector('#userForm')?.addEventListener('reset',()=>setTimeout(()=>{const form=document.querySelector('#userForm');if(form){form.elements.id.value='';document.querySelector('#userFormHeading').textContent='Add customer'}},0));
  document.querySelectorAll('[data-edit-user]').forEach(button=>button.addEventListener('click',()=>{const user=adminUsers.find(item=>String(item.id)===button.dataset.editUser),form=document.querySelector('#userForm');if(!user||!form)return;form.elements.id.value=user.id;form.elements.name.value=user.name;form.elements.email.value=user.email;form.elements.phone.value=user.phone||'';document.querySelector('#userFormHeading').textContent='Edit customer';form.scrollIntoView({behavior:'smooth',block:'center'})}));
  document.querySelectorAll('[data-delete-user]').forEach(button=>button.addEventListener('click',async()=>{if(!confirm('Delete this customer record?'))return;try{await deleteAdminUser(button.dataset.deleteUser);adminUsers=await getAdminUsers();renderAdminView();showToast('Customer deleted')}catch(error){showToast(error.message)}}));
  document.querySelector('#menuSettingsForm')?.addEventListener('submit',async event=>{event.preventDefault();const values=new FormData(event.currentTarget);adminMenuData.fees=adminMenuData.fees||{};adminMenuData.fees.service=Number(values.get('service'));for(const [group,options] of Object.entries(adminMenuData.options)){for(const option of options){const value=values.get(`${group}:${option.id}`);if(value!==null)option.price=Number(value)}}try{await persistAdminMenu()}catch(error){showToast(error.message)}});
  const gestureHelp=document.querySelector('#gestureIndicatorName');if(gestureHelp&&browserCameraStream)gestureHelp.textContent='Pinch, grab a control, then release';
  view.querySelectorAll('.queue-column').forEach(column=>{column.addEventListener('dragover',event=>event.preventDefault());column.addEventListener('drop',async event=>{event.preventDefault();const id=event.dataTransfer?.getData('text/order-id');if(id)await dropOrderOnStatus(id,column.dataset.dropStatus)})});
  view.querySelectorAll('.admin-order-card').forEach(card=>{card.draggable=true;card.addEventListener('dragstart',event=>event.dataTransfer?.setData('text/order-id',card.dataset.orderId))});
}
async function dropOrderOnStatus(id,status){try{await changeStatus(id,status);showToast(`Order moved to ${status.toLowerCase()}`);await renderKitchen()}catch(error){showToast(error.message)}}
document.querySelector('#adminAccess').addEventListener('click',()=>{if(location.hash==='#admin')openAdmin();else location.hash='admin'});window.addEventListener('hashchange',()=>{if(location.hash==='#admin')openAdmin()});if(location.hash==='#admin')openAdmin();
function connectGestures(){if(!browserCameraStream||cameraDisabled||!preferBrowserCamera||!handTracker)return;if(gestureSocket&&gestureSocket.readyState<2)return;const proto=location.protocol==='https:'?'wss':'ws';const ws=gestureSocket=new WebSocket(proto+'://'+location.host+'/ws/gestures/landmarks');ws.onopen=()=>{handTracker.onResults(results=>{drawHandLandmarks(results);const points=results.multiHandLandmarks?.[0]?.map(point=>[point.x,point.y])||[];updateHandPointer(points);const stablePoints=points.length?points:(Date.now()-lastHandSeenAt<180?lastHandPoints||[]:[]);if(ws.readyState===WebSocket.OPEN)ws.send(JSON.stringify({landmarks:stablePoints}))});const source=document.querySelector('#cameraSource');cameraFrameTimer=setInterval(()=>{if(ws.readyState!==WebSocket.OPEN||!source?.videoWidth||cameraFramePending)return;cameraFramePending=true;handTracker.send({image:source}).catch(()=>{}).finally(()=>{cameraFramePending=false})},75)};ws.onmessage=event=>{const message=JSON.parse(event.data);const label=document.querySelector('#cameraLabel');const help=document.querySelector('#helpCameraStatus');if(message.type==='error'){if(label)label.textContent='Gesture controls unavailable';if(help)help.textContent='Camera preview is on, but gesture controls could not connect';return}if(message.type==='status'||message.type==='gesture'){updateGestureIndicator(message.detected||'no_hand',message.confidence||0);const labels={no_hand:'Show one hand',one_finger:'Pointing',two_fingers:'Two fingers detected',open_palm:'Open palm detected',fist:'Hold fist to cancel',pinch:'Pinch detected',thumbs_up:'Thumbs up detected',thumbs_down:'Thumbs down detected',hand:'Hand detected'};const text=labels[message.detected]||'Show one hand';if(label)label.textContent=text;if(help)help.textContent=text;document.querySelector('#cameraDot')?.style.setProperty('background','var(--green)');document.querySelector('.camera-pill')?.classList.remove('offline')}if(message.type==='gesture')handleGesture(message.gesture)};ws.onerror=()=>{const help=document.querySelector('#helpCameraStatus');if(help)help.textContent='Camera preview is on; reconnecting gesture controls'};ws.onclose=()=>{if(cameraFrameTimer){clearInterval(cameraFrameTimer);cameraFrameTimer=null}if(gestureSocket===ws)gestureSocket=null;if(browserCameraStream&&!cameraDisabled)setTimeout(connectGestures,1200)}}
init();connectGestures();

